export const MEMORY_RAW_LIMIT = 200
export const MEMORY_AUDIT_LIMIT = 500
export const MEMORY_CONTENT_LIMIT = 320
export const IMPORT_IMPORTANCE = 4
/** 正文 Dice 达到此值即视为同一条。 */
export const MEMORY_OVERLAP_CONTENT = 0.7
/** 标题 Dice 达到此值即视为同一条。 */
