  const sig = top.map((e) => e.pattern + 'x' + e.hits).join('|');
  if (state.lessonsSig === sig && !force) return null;
  state.lessonsSig = sig;
  const lines = ['📚 【AI 抬头 · 已知坑位】请勿重复:'];
