    return lines.join("\n");
  }
  if (action === "get") {
    lines.push(`chars: ${payload.chars ?? 0}${payload.truncated ? " (truncated)" : ""}`);
    lines.push("---");
    lines.push(payload.text ?? "");
  } else {
    lines.push(`chars: ${payload.chars ?? 0}`);
    lines.push("status: set");
  }
  return lines.join("\n");
}
